CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE IF NOT EXISTS news_items (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), headline TEXT NOT NULL, summary TEXT, source TEXT NOT NULL, source_id TEXT, url TEXT UNIQUE NOT NULL, published_at TIMESTAMPTZ NOT NULL, image_url TEXT, teams TEXT[] DEFAULT '{}', sentiment_score NUMERIC, sentiment_label TEXT CHECK (sentiment_label IN ('positive', 'neutral', 'negative')), sentiment_breakdown JSONB, sentiment_source TEXT, sentiment_comment_count INTEGER DEFAULT 0, sentiment_analyzed_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_news_items_url ON news_items(url);
CREATE INDEX IF NOT EXISTS idx_news_items_published ON news_items(published_at DESC);
CREATE INDEX IF NOT EXISTS idx_news_items_teams ON news_items USING GIN(teams);
CREATE TABLE IF NOT EXISTS polls (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), question TEXT NOT NULL, options JSONB NOT NULL DEFAULT '[]', event_context TEXT, active BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_polls_active ON polls(active) WHERE active = TRUE;
CREATE TABLE IF NOT EXISTS poll_responses (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), poll_id UUID NOT NULL REFERENCES polls(id) ON DELETE CASCADE, option_index INTEGER NOT NULL, ip_address TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(poll_id, ip_address));
CREATE INDEX IF NOT EXISTS idx_poll_responses_lookup ON poll_responses(poll_id, ip_address);
ALTER TABLE news_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE polls ENABLE ROW LEVEL SECURITY;
ALTER TABLE poll_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY "News items are viewable by everyone" ON news_items FOR SELECT USING (true);
CREATE POLICY "News items are insertable by service role" ON news_items FOR INSERT WITH CHECK (auth.role() = 'service_role');
CREATE POLICY "News items are updatable by service role" ON news_items FOR UPDATE USING (auth.role() = 'service_role');
CREATE POLICY "Polls are viewable by everyone" ON polls FOR SELECT USING (true);
CREATE POLICY "Polls are insertable by service role" ON polls FOR INSERT WITH CHECK (auth.role() = 'service_role');
CREATE POLICY "Polls are updatable by service role" ON polls FOR UPDATE USING (auth.role() = 'service_role');
CREATE POLICY "Poll responses are insertable by service role" ON poll_responses FOR INSERT WITH CHECK (auth.role() = 'service_role');
CREATE POLICY "Poll responses are viewable by service role" ON poll_responses FOR SELECT USING (auth.role() = 'service_role');
