CREATE OR REPLACE FUNCTION cleanup_old_news() RETURNS void AS $$ BEGIN DELETE FROM news_items WHERE created_at < NOW() - INTERVAL '7 days'; END; $$ LANGUAGE plpgsql;
CREATE TABLE IF NOT EXISTS article_comments (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), article_url TEXT NOT NULL REFERENCES news_items(url) ON DELETE CASCADE, comment_text TEXT NOT NULL, author_name TEXT NOT NULL DEFAULT 'Anonymous', published_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), like_count INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_article_comments_url ON article_comments(article_url);
CREATE INDEX IF NOT EXISTS idx_article_comments_likes ON article_comments(article_url, like_count DESC);
ALTER TABLE article_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Article comments are viewable by everyone" ON article_comments FOR SELECT USING (true);
CREATE POLICY "Article comments are insertable by service role" ON article_comments FOR INSERT WITH CHECK (auth.role() = 'service_role');
CREATE POLICY "Article comments are deletable by service role" ON article_comments FOR DELETE USING (auth.role() = 'service_role');
